    public required IReadOnlyList<string>? TargetPath { get; init; }

    [JsonPropertyName("extensions")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public IReadOnlyDictionary<string, JsonElement>? Extensions { get; init; }
}

/// <summary>
/// A trigger's declaration. The body is never recorded.
/// </summary>
public sealed record SqlTrigger {
    [JsonPropertyName("id")]
    public required string Id { get; init; }

    [JsonPropertyName("path")]
    public required IReadOnlyList<string> Path { get; init; }

    /// <summary>
    /// Permitted values: dml, ddl.
    /// </summary>
    [JsonPropertyName("kind")]
    public required string Kind { get; init; }

    [JsonPropertyName("description")]
    public required string? Description { get; init; }

    /// <summary>
    /// Id of the table the trigger is attached to, or null for a DDL trigger.
    /// </summary>
    [JsonPropertyName("table")]
    public required string? Table { get; init; }

    /// <summary>
    /// Permitted values: before, after, insteadOf.
    /// </summary>
    [JsonPropertyName("timing")]
    public required string Timing { get; init; }

    /// <summary>
    /// For a DML trigger: insert, update, delete. For a DDL trigger: the DDL event names.
    /// </summary>
    [JsonPropertyName("events")]
    public required IReadOnlyList<string> Events { get; init; }

    [JsonPropertyName("disabled")]
    public required bool Disabled { get; init; }

    [JsonPropertyName("extensions")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public IReadOnlyDictionary<string, JsonElement>? Extensions { get; init; }
}

/// <summary>
/// The annotation sidecar: prose a compiled model cannot carry. Reachable from nothing in the
/// payload -- it is a separate document a producer is handed, and it is defined here so the
/// type is generated in both languages from one source rather than hand-written twice.
/// </summary>
public sealed record SqlAnnotations {
    [JsonPropertyName("schemaVersion")]
    public required string SchemaVersion { get; init; }

    /// <summary>
    /// Maps an object address to its description. The address is an object's id for a top-level
    /// object, and '&lt;owner id&gt;.&lt;name&gt;' for a nested column, constraint, index or parameter. A key
    /// matching nothing in the document is an error: a stale annotation naming a dropped column is
    /// the failure this file exists to prevent.
    /// </summary>
    [JsonPropertyName("descriptions")]
    public required IReadOnlyDictionary<string, string> Descriptions { get; init; }
}

